CREATE TABLE IF NOT EXISTS pt (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, created_at DATETIME(3) NOT NULL, PRIMARY KEY (id, created_at)) ENGINE=InnoDB PARTITION BY RANGE COLUMNS(created_at) (PARTITION p1 VALUES LESS THAN ('2026-12-01'));
GRANT SELECT, INSERT, UPDATE, DELETE ON `pt` TO lingedge_app;
GRANT SELECT, ALTER, DROP ON `pt` TO lingedge_maint;
